#pragma once
#include <stdint.h>

// The pet's sounds, 16 kHz mono PCM in flash (sounds.cpp is generated by
// firmware/tools/sounds.py from a pack in assets/sounds/pet/).

enum Sound : uint8_t { SND_ANNOYED, SND_GIGGLE, SND_HELLO, SND_HUNGRY, SND_LOVE, SND_MUNCH, SND_STARTLED, SND_YAWN, SND_COUNT };

struct SoundClip {
  const int16_t *samples;
  uint32_t count;
};

static constexpr uint32_t SOUND_RATE = 16000;

extern const SoundClip SOUNDS[SND_COUNT];
